      "description": "The sprawl of tethers where ships berth against the comet's slow spin."
    },
    {
      "id": "loc_map_house",
      "name": "The Map House",
      "description": "The guild house where star-maps are drawn, sealed and registered."
    },
    {
      "id": "loc_cinder_gardens",
      "name": "The Cinder Gardens",
      "description": "Sunward glasshouses in the slag skin where growers farm the perihelion light."
    },
    {
      "id": "loc_long_hall",
      "name": "The Long Hall",
      "description": "The arbitration hall where claims are heard under the burn articles."
    }
  ],
  "factions": [
    {
      "id": "fac_mapmakers",
      "name": "The Mapmakers' Guild",
      "description": "The guild that draws, seals and arbitrates every registered star-map.",
      "location_ids": [
        "loc_map_house",
        "loc_long_hall"
      ]
    },
    {
      "id": "fac_ice_barons",
      "name": "The Ice Barons",
      "description": "Claim-holders who mine the core and buy up tethers before each burn.",
      "location_ids": [
        "loc_core_vaults"
      ]
    },
    {
      "id": "fac_free_pilots",
      "name": "The Free Pilots' Compact",
      "description": "Independent pilots who fly the routes the guilds only chart.",
      "location_ids": [
        "loc_tether_docks"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_burn_articles",
      "statement": "At perihelion every claim is settled or forfeited; nothing litigates through the burn.",
      "category": "social"
    },
    {
      "id": "rul_map_seal",
      "statement": "A sealed star-map may be opened only by its sealer or by the arbiter of the Long Hall.",
      "category": "social"
    },
    {
      "id": "rul_no_energy_arms",
      "statement": "Weapons aboard are blades, tools and harpoons; powered arms breach the market's charter.",
      "category": "technology"
    },
    {
